SELECT result_tags AS tags, any(timestamp) AS timestamp, any(value) AS value FROM (SELECT arrayFilter(tag -> tag.1 != '__name__', arraySort(tag -> tag.1, arrayFilter(tag -> has(['instance'], tag.1), lhs.original_group))) AS result_tags, lhs.timestamp AS timestamp, (lhs.value + rhs.value) AS value FROM (SELECT any(tags) AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> has(['instance'], tag.1), tags)) AS join_group, any(timestamp) AS timestamp, any(value) AS value FROM (
    SELECT series.tags AS tags, fromUnixTimestamp64Milli(1700000000000) AS timestamp, argMax(d.value, d.timestamp) AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
        SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {lhs_instant_matcher_0_value:String} AND src.tags[concat('', {lhs_instant_matcher_1_key:String})] = {lhs_instant_matcher_1_value:String} AND src.max_time >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64})
    ) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64}) GROUP BY d.id, series.tags HAVING NOT isNaN(value) ORDER BY tags
) GROUP BY arraySort(tag -> tag.1, arrayFilter(tag -> has(['instance'], tag.1), tags)) HAVING throwIf(count() > 1, 'found duplicate series for the match group on the lhs hand-side of the operation') = 0) AS lhs INNER JOIN (SELECT any(tags) AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> has(['instance'], tag.1), tags)) AS join_group, any(timestamp) AS timestamp, any(value) AS value FROM (
    SELECT series.tags AS tags, fromUnixTimestamp64Milli(1700000000000) AS timestamp, argMax(d.value, d.timestamp) AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
        SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {rhs_instant_matcher_0_value:String} AND src.tags[concat('', {rhs_instant_matcher_1_key:String})] = {rhs_instant_matcher_1_value:String} AND src.max_time >= fromUnixTimestamp64Milli({rhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({rhs_required_end_ms:Int64})
    ) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({rhs_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({rhs_required_end_ms:Int64}) GROUP BY d.id, series.tags HAVING NOT isNaN(value) ORDER BY tags
) GROUP BY arraySort(tag -> tag.1, arrayFilter(tag -> has(['instance'], tag.1), tags)) HAVING throwIf(count() > 1, 'found duplicate series for the match group on the rhs hand-side of the operation') = 0) AS rhs ON lhs.join_group = rhs.join_group) GROUP BY result_tags HAVING throwIf(count() > 1, 'multiple matches for labels: grouping labels must ensure unique matches') = 0 ORDER BY result_tags
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
